/// Returns the `n`th Fibonacci number, where `fib(0) == 0` and `fib(1) == 1`.
pub fn fib(n: u64) -> u64 {
    match n {
        0 => 0,
        1 => 1,
        _ => fib(n - 1) + fib(n - 2),
    }
}

#[test]
